import{_ as r,l as t,o as a,c as s,v as o,p as l,x as d,d as i,i as n,S as E}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"聚合与 GROUP BY","description":"","frontmatter":{"title":"聚合与 GROUP BY","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sql-aggregation.md","filePath":"cs/sql-aggregation.md","lastUpdated":1789023840000}'),p={name:"cs/sql-aggregation.md"};function h(B,e,m,R,_,A){const c=t("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="聚合与-group-by" tabindex="-1">聚合与 GROUP BY <a class="header-anchor" href="#聚合与-group-by" aria-label="Permalink to &quot;聚合与 GROUP BY&quot;">​</a></h1><div class="epigraph"><p>分组把包切成等价类，聚合把每一类收成一行标量；结果仍是关系，只是属性不再是输入列的简单子集。</p><footer>—— 据 Chamberlin and Boyce, SEQUEL, 1974；SQL 标准对 GROUP BY；Ramakrishnan and Gehrke 对聚合算子的整理</footer></div><p><a href="/cs/app-backpressure">上一课</a>把计算机网络进阶收到应用背压。本课打开数据库进阶：主干 <a href="/cs/sql-declarative">SQL 声明</a> 已把 <code>SELECT</code>–<code>FROM</code>–<code>WHERE</code> 钉在代数上，并点名分组「把元组集收成组上的标量」，但没有机制。缺口不是重讲投影，而是 <strong>GROUP BY 如何改变结果模式</strong>，以及 <code>HAVING</code> 与 <code>WHERE</code> 为何不能互换。不重写 Transformer，不进限价簿。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>声明课把查询收成代数树。连接与选择之后，用户仍要「每个顾客多少订单」「每个月合计」。若应用拉回全部行再自己加，等于放弃声明性，优化器看不见分组。缺口是语言里的分组算子：按一组列划等价类，每组产出一行；<code>COUNT</code>/<code>SUM</code>/<code>AVG</code>/<code>MIN</code>/<code>MAX</code> 是组上的函数，不是行上的投影。</p><p><code>WHERE</code> 在分组前滤行；<code>HAVING</code> 在分组后滤组。把聚合写进 <code>WHERE</code> 没有指称。未分组查询里的裸聚合把整张输入当成一组。<code>SELECT</code> 列表在有 <code>GROUP BY</code> 时只能出现分组列或聚合——否则一行组无法决定「其余列取哪一个值」。</p><p><span class="marginnote">SQL 默认包：同一组里重复行计入 <code>COUNT(*)</code>。<code>COUNT(col)</code> 不计该列上的 NULL。<code>SUM</code> 全 NULL 组得 NULL 不是 0。三值逻辑仍是 <a href="/cs/sql-null">空值</a> 那一套，本课不重推。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>逻辑上看，分组是 \\(\\gamma_{G,A}(R)\\)：按 \\(G\\) 分组，算聚合列表 \\(A\\)，输出模式是 \\(G\\) 加上各聚合的结果列。物理实现可以排序后扫描相邻组，或哈希建桶——算子形状后课 <a href="/cs/hash-aggregation">哈希聚合</a> 才写；本课只要求语义先钉住。</p><p><code>DISTINCT</code> 聚合（<code>COUNT(DISTINCT x)</code>）先在组内去重再聚合。过滤聚合（<code>FILTER (WHERE …)</code>）是组内再选，不等于外层 <code>WHERE</code>。本课不把每个方言的 <code>GROUPING SETS</code> 当必会语法，只点名：同一输入上多个分组集是多个 \\(\\gamma\\) 的并。</p>',10)),(a(),l(E,null,{default:d(()=>[n(c,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%BE%93%E5%85%A5%E5%8C%85%22%5D%20--%3E%20WHERE%5B%22WHERE%20%E6%BB%A4%E8%A1%8C%22%5D%0A%20%20WHERE%20--%3E%20GRP%5B%22%E6%8C%89%20G%20%E5%88%92%E7%BB%84%22%5D%0A%20%20GRP%20--%3E%20AGG%5B%22%E7%BB%84%E4%B8%8A%E8%81%9A%E5%90%88%22%5D%0A%20%20AGG%20--%3E%20HAV%5B%22HAVING%20%E6%BB%A4%E7%BB%84%22%5D%0A%20%20HAV%20--%3E%20OUT%5B%22%E7%BB%93%E6%9E%9C%E5%85%B3%E7%B3%BB%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分组挡住若干代数律：不能把组后谓词随便推到组前，除非谓词只谈 \\(G\\) 且不含聚合。连接与分组的交换要看键：若连接键是分组键的超集，有时可先聚后连以缩小输入——这是改写，不是改语义。优化器后课会搜这些形状；本课只承认分组是改写防火墙之一，与 <a href="/cs/query-rewrite">查询改写</a> 点名的窗口、极限同类。</p><p>空组：<code>FROM</code> 为空时，无 <code>GROUP BY</code> 的裸聚合仍产出一行（<code>COUNT(*)</code> 为 0）；有 <code>GROUP BY</code> 则零行。这是标准里的坑，声明含义必须包含它，否则「有没有分组」会改结果基数。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲窗口函数：窗口也聚合，但不把多行收成一行，组的边界与帧不同。子查询里的聚合、相关与否，下一课之后才去相关。也不把 OLAP 立方、<code>CUBE</code>/<code>ROLLUP</code> 的稀疏格写进本课必做。</p><p>存储与索引：分组列上的有序扫描能省排序，那是计划选择，不是 GROUP BY 的定义。后课默认：谈到分组查询，先有 \\(\\gamma\\) 的模式与空组规则；物理是排序或哈希，语义不是循环加器。</p><p>主干连接算法课未改分组语义。进阶从这里把查询语言从「行过滤」接到「组收缩」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>GROUP BY</code> 按列划组，聚合把每组收成一行；<code>HAVING</code> 滤组，<code>WHERE</code> 滤行。</li><li>未分组的裸聚合视整表为一组；空输入时与有分组的基数规则不同。</li><li>分组是改写防火墙；窗口函数下一课，形状不同。</li><li>出处：Chamberlin and Boyce；SQL 标准；Ramakrishnan and Gehrke。</li></ul>',9))])}const P=r(p,[["render",h]]);export{T as __pageData,P as default};
